    int counter = 0;
    while (it.hasNext()) {
        Object obj = it.next();
        assertNotNull(obj);
        assertTrue(obj instanceof Persistent);
        // iterator must be resolved page by page
        int expectedResolved = list.pageIndex(counter) * list.getPageSize() + list.getPageSize();
