@Test
public void testEncrypt_StringToString() throws UnsupportedEncodingException, IllegalBlockSizeException, BadPaddingException {
    DefaultValueEncryptor e = new DefaultValueEncryptor(Utf8StringConverter.INSTANCE, Base64StringConverter.INSTANCE);
    String s1 = "ab";
    // try to get beyond a single block boundary and a Base64 line...
    String s2 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. " + "Pellentesque nisi sapien, mattis eu porttitor in, tempus quis lorem. " + "Integer vel dignissim quam. Maecenas pellentesque est erat, eget semper ipsum aliquet vitae. " + "Donec convallis mi vitae luctus rutrum. Sed ut imperdiet ante. Praesent condimentum velit eget " + "felis pretium blandit. Praesent lacus tortor, facilisis eget sapien quis, hendrerit iaculis tellus.";
    String s1_t = (String) e.encrypt(encryptor, s1);
    assertNotNull(s1_t);
    assertNotEquals(s1_t, s1);
    byte[] b1_t = Base64.getDecoder().decode(s1_t);
    assertEquals(s1, new String(decryptor.decrypt(b1_t, 0, null), Utf8StringConverter.DEFAULT_CHARSET));
    String s2_t = (String) e.encrypt(encryptor, s2);
    assertNotNull(s2_t);
    assertNotEquals(s2_t, s2);
    byte[] b2_t = Base64.getDecoder().decode(s2_t);
    assertEquals(s2, new String(decryptor.decrypt(b2_t, 0, null), Utf8StringConverter.DEFAULT_CHARSET));
}

