    assertTrue(a3.isPostAdded());
    assertSame(a3, listener2.getPublicCalledbackEntity());
    Painting p3 = context.newObject(Painting.class);
    assertNotNull(p3);
    assertFalse(p3.isPostAdded());
    assertSame(a3, listener2.getPublicCalledbackEntity());
}

