            assertEquals(newAltName, altArtist.getArtistName());
            assertEquals(newDate, altArtist.getDateOfBirth());
            assertEquals(PersistenceState.MODIFIED, altArtist.getPersistenceState());
        }
    };
    helper.runTest(3000);
}

