@Test
public void testExplicitDistinct() throws Exception {
    tArtist.insert(21, "artist1", null);
    List<String> result = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME).select(context);
    assertEquals(21, result.size());
    List<String> result2 = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME).suppressDistinct().select(context);
    assertEquals(result, result2);
    result = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME).distinct().select(context);
    assertEquals(20, result.size());
}

@Test
public void testSuppressDistinct() throws Exception {
    // create non unique artist name / painting name pair
    tArtist.insert(21, "artist1", null);
    tPaintings.insert(22, "painting10", 21, 1, 23);
    List<Object[]> result = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME, Artist.PAINTING_ARRAY.dot(Painting.PAINTING_TITLE)).select(context);
    assertEquals(21, result.size());
    List<Object[]> result2 = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME, Artist.PAINTING_ARRAY.dot(Painting.PAINTING_TITLE)).distinct().select(context);
    assertEquals(result.size(), result2.size());
    for (int i = 0; i < result.size(); i++) {
        assertArrayEquals(result.get(i), result2.get(i));
    }
    result = ObjectSelect.columnQuery(Artist.class, Artist.ARTIST_NAME, Artist.PAINTING_ARRAY.dot(Painting.PAINTING_TITLE)).suppressDistinct().select(context);
    assertEquals(22, result.size());
}

