    List<?> artists = runProcedureSelect(MappedSelect.query("ProcedureQuery", Artist.class).param("aName", "An Artist").param("paintingPrice", 3000).forceNoCache()).firstList();
    // check the results
    assertNotNull("Null result from StoredProcedure.", artists);
    assertEquals(1, artists.size());
    Artist artistRow = (Artist) artists.get(0);
    assertEquals("An Artist", artistRow.getArtistName());
}

