    exhibitEntity.removeRelationship("artistExhibitArray");
    Expression e = ExpressionFactory.matchExp("artistName", "artist1");
    SelectQuery<Artist> q = new SelectQuery<>(Artist.class, e);
    q.addPrefetch("paintingArray");
