    assertEquals(2, resources3.size());
    Resource[] resources3a = resources3.toArray(new Resource[2]);
    assertEquals(f1.toURI().toURL(), resources3a[0].getURL());
    assertEquals(f2.toURI().toURL(), resources3a[1].getURL());
}

