@Test
public void testQualifyOnToMany() {
    ReflexiveAndToOne ox = context.newObject(ReflexiveAndToOne.class);
    ox.setName("ox");
    ReflexiveAndToOne o1 = context.newObject(ReflexiveAndToOne.class);
    o1.setName("o1");
    ReflexiveAndToOne o2 = context.newObject(ReflexiveAndToOne.class);
    o2.setName("o2");
    o2.setToParent(o1);
    context.commitChanges();
    Expression qualifier = ExpressionFactory.matchExp("children", o2);
    List<?> parents = SelectQuery.query(ReflexiveAndToOne.class, qualifier).select(context);
    assertEquals(1, parents.size());
    assertSame(o1, parents.get(0));
    qualifier = ExpressionFactory.matchExp("children", o1);
    parents = SelectQuery.query(ReflexiveAndToOne.class, qualifier).select(context);
    assertEquals(0, parents.size());
}

@Test
public void testQualifyOnToOne() {
    ReflexiveAndToOne ox = context.newObject(ReflexiveAndToOne.class);
    ox.setName("ox");
    ReflexiveAndToOne o1 = context.newObject(ReflexiveAndToOne.class);
    o1.setName("o1");
    ReflexiveAndToOne o2 = context.newObject(ReflexiveAndToOne.class);
    o2.setName("o2");
    o2.setToParent(o1);
    context.commitChanges();
    Expression qualifier = ExpressionFactory.matchExp("toParent", o1);
    List<ReflexiveAndToOne> children = SelectQuery.query(ReflexiveAndToOne.class, qualifier).select(context);
    assertEquals(1, children.size());
    assertSame(o2, children.get(0));
    o2.setToParent(null);
    context.commitChanges();
}

@Test
public void testLoad2MapsWithCrossMapInheritance() throws Exception {
    Injector injector = DIBootstrap.createInjector(new ServerModule() {

        @Override
        public void configure(Binder binder) {
            super.configure(binder);
            ServerModule.contributeProjectLocations(binder).add("cay743/cayenne-domain.xml");
        }
    });
    try {
        DataDomain domain = injector.getInstance(DataDomain.class);
        assertEquals(2, domain.getDataMaps().size());
        DataMap m1 = domain.getDataMap("map1");
        DataMap m2 = domain.getDataMap("map2");
        ObjEntity oe11 = m1.getObjEntity("Entity11");
        ObjEntity oe12 = m1.getObjEntity("Entity12");
        ObjEntity oe21 = m2.getObjEntity("Entity21");
        ObjEntity oe22 = m2.getObjEntity("Entity22");
        // this causes StackOverflow per CAY-743
        ObjEntity oe21Super = oe21.getSuperEntity();
        ObjEntity oe12Super = oe12.getSuperEntity();
        assertSame(oe12Super, oe22);
        assertSame(oe21Super, oe11);
    } finally {
        injector.shutdown();
    }
}

