public void testFilterParameters() {
    MockFilterConfig config1 = new MockFilterConfig();
    config1.setFilterName("cayenne-x");
    config1.setInitParameter(WebConfiguration.CONFIGURATION_LOCATION_PARAMETER, "cayenne-y.xml");
